// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// RiskGetActivityChecklist One checklist run by id (RRA-05)
	// (GET /admin/v1/risk/activity-checklists/{id})
	RiskGetActivityChecklist(ctx context.Context, request RiskGetActivityChecklistRequestObject) (RiskGetActivityChecklistResponseObject, error)
	// RiskListHighRiskActivityScores RRA-11: every activity whose own latest score is high/very_high right now — "กิจกรรมเสี่ยงสูงแสดงเด่นทั้งในรายการและแผนผัง", for highlighting on both the RoPA list and the data flow diagram
	// (GET /admin/v1/risk/activity-scores/high-risk)
	RiskListHighRiskActivityScores(ctx context.Context, request RiskListHighRiskActivityScoresRequestObject) (RiskListHighRiskActivityScoresResponseObject, error)
	// RiskListComplianceScoreReport RRA-13's own "ตารางคะแนนรายหน่วยงาน": every org unit's averaged, explained compliance score, for comparing and tracking progress
	// (GET /admin/v1/risk/compliance-score)
	RiskListComplianceScoreReport(ctx context.Context, request RiskListComplianceScoreReportRequestObject) (RiskListComplianceScoreReportResponseObject, error)
	// RiskGetOrgUnitComplianceScore RRA-13: one org unit's compliance score — every activity under it, each with its own explained score, averaged
	// (GET /admin/v1/risk/compliance-score/{orgUnitId})
	RiskGetOrgUnitComplianceScore(ctx context.Context, request RiskGetOrgUnitComplianceScoreRequestObject) (RiskGetOrgUnitComplianceScoreResponseObject, error)
	// RiskListOpenGapFindings The tenant-wide gap register (RRA-04) — every open finding across every activity, newest first
	// (GET /admin/v1/risk/gap-findings)
	RiskListOpenGapFindings(ctx context.Context, request RiskListOpenGapFindingsRequestObject) (RiskListOpenGapFindingsResponseObject, error)
	// RiskRemediateGapFinding RRA-07: open a dpo.tasks remediation job against an open gap finding, with an assignee, due date and priority
	// (POST /admin/v1/risk/gap-findings/{id}/remediate)
	RiskRemediateGapFinding(ctx context.Context, request RiskRemediateGapFindingRequestObject) (RiskRemediateGapFindingResponseObject, error)
	// RiskListGapRules Every active legal-gap rule (RRA-04) — code, severity and the legal article it cites
	// (GET /admin/v1/risk/gap-rules)
	RiskListGapRules(ctx context.Context, request RiskListGapRulesRequestObject) (RiskListGapRulesResponseObject, error)
	// RiskListMatrices The tenant's own likelihood x impact risk matrices, default first (RRA-02)
	// (GET /admin/v1/risk/matrices)
	RiskListMatrices(ctx context.Context, request RiskListMatricesRequestObject) (RiskListMatricesResponseObject, error)
	// RiskCreateMatrix Create a risk matrix
	// (POST /admin/v1/risk/matrices)
	RiskCreateMatrix(ctx context.Context, request RiskCreateMatrixRequestObject) (RiskCreateMatrixResponseObject, error)
	// RiskDeleteMatrix Remove a risk matrix (If-Match = its own ETag)
	// (DELETE /admin/v1/risk/matrices/{id})
	RiskDeleteMatrix(ctx context.Context, request RiskDeleteMatrixRequestObject) (RiskDeleteMatrixResponseObject, error)
	// RiskGetMatrix One risk matrix
	// (GET /admin/v1/risk/matrices/{id})
	RiskGetMatrix(ctx context.Context, request RiskGetMatrixRequestObject) (RiskGetMatrixResponseObject, error)
	// RiskUpdateMatrix Change a risk matrix's own levels, thresholds or default flag — the acceptance criterion itself (RRA-02), since Classify always reads the current row live, never a cached score
	// (PUT /admin/v1/risk/matrices/{id})
	RiskUpdateMatrix(ctx context.Context, request RiskUpdateMatrixRequestObject) (RiskUpdateMatrixResponseObject, error)
	// RiskGetExecutiveReport RRA-14: a one-click executive summary of every still-open high/very-high risk from the risk register (RRA-09) — its owner and its own remediation task's current progress
	// (GET /admin/v1/risk/report)
	RiskGetExecutiveReport(ctx context.Context, request RiskGetExecutiveReportRequestObject) (RiskGetExecutiveReportResponseObject, error)
	// RiskListRisks RRA-09: the shared privacy risk register — every risk.risks row regardless of source (DPIA / RoPA activity / vendor / breach / audit / manual), newest first
	// (GET /admin/v1/risk/risks)
	RiskListRisks(ctx context.Context, request RiskListRisksRequestObject) (RiskListRisksResponseObject, error)
	// RiskCreateRisk RRA-09: log a risk directly into the register — a RoPA activity, a system (ropa.assets) or a vendor, or a plain manual entry; DPIA-06's own DpiaIdentifyRisk covers the dpia-sourced case
	// (POST /admin/v1/risk/risks)
	RiskCreateRisk(ctx context.Context, request RiskCreateRiskRequestObject) (RiskCreateRiskResponseObject, error)
	// RiskGetRisk RRA-09: one register entry by id
	// (GET /admin/v1/risk/risks/{id})
	RiskGetRisk(ctx context.Context, request RiskGetRiskRequestObject) (RiskGetRiskResponseObject, error)
	// RiskUpdateRiskEntry RRA-09: edit a register entry's own title/description/owner/score/treatment/status — never its activity/asset/vendor link, which is set only at creation
	// (PUT /admin/v1/risk/risks/{id})
	RiskUpdateRiskEntry(ctx context.Context, request RiskUpdateRiskEntryRequestObject) (RiskUpdateRiskEntryResponseObject, error)
	// RiskListAcceptances RRA-08: every acceptance ever recorded for a risk, newest first
	// (GET /admin/v1/risk/risks/{id}/acceptances)
	RiskListAcceptances(ctx context.Context, request RiskListAcceptancesRequestObject) (RiskListAcceptancesResponseObject, error)
	// RiskRecordAcceptance RRA-08: record acceptance of the risk's own residual as-is, with a reason and a review date — flips the risk to status=accepted and schedules the one reminder at expires_at
	// (POST /admin/v1/risk/risks/{id}/acceptances)
	RiskRecordAcceptance(ctx context.Context, request RiskRecordAcceptanceRequestObject) (RiskRecordAcceptanceResponseObject, error)
	// RiskListActivityChecklists Every checklist run recorded against this activity, newest first (RRA-05)
	// (GET /admin/v1/ropa/activities/{id}/checklists)
	RiskListActivityChecklists(ctx context.Context, request RiskListActivityChecklistsRequestObject) (RiskListActivityChecklistsResponseObject, error)
	// RiskAnswerActivityChecklist Answer a published checklist against this activity and record the run (RRA-05)
	// (POST /admin/v1/ropa/activities/{id}/checklists)
	RiskAnswerActivityChecklist(ctx context.Context, request RiskAnswerActivityChecklistRequestObject) (RiskAnswerActivityChecklistResponseObject, error)
	// RiskGetActivityComplianceScore RRA-13: one activity's compliance score (100 minus a point deduction per still-open gap finding, RRA-04) — the acceptance criterion itself, every deduction names the gap it came from
	// (GET /admin/v1/ropa/activities/{id}/compliance-score)
	RiskGetActivityComplianceScore(ctx context.Context, request RiskGetActivityComplianceScoreRequestObject) (RiskGetActivityComplianceScoreResponseObject, error)
	// RiskAnalyzeActivity Re-run every active gap rule against this activity's current RoPA data now (RRA-04) — the acceptance criterion itself, since every rule type must be detected
	// (POST /admin/v1/ropa/activities/{id}/gap-analysis)
	RiskAnalyzeActivity(ctx context.Context, request RiskAnalyzeActivityRequestObject) (RiskAnalyzeActivityResponseObject, error)
	// RiskListActivityGapFindings This activity's own gap findings (RRA-04), as last analyzed — read-only, no recomputation
	// (GET /admin/v1/ropa/activities/{id}/gap-findings)
	RiskListActivityGapFindings(ctx context.Context, request RiskListActivityGapFindingsRequestObject) (RiskListActivityGapFindingsResponseObject, error)
	// RiskGetLatestActivityScore The activity's most recently computed risk score, without recomputing (RRA-01)
	// (GET /admin/v1/ropa/activities/{id}/risk-score)
	RiskGetLatestActivityScore(ctx context.Context, request RiskGetLatestActivityScoreRequestObject) (RiskGetLatestActivityScoreResponseObject, error)
	// RiskScoreActivity Compute a fresh risk score from the activity's current RoPA data and record it (RRA-01) — the acceptance criterion itself, since this always reads live data and explains the contributing factors
	// (POST /admin/v1/ropa/activities/{id}/risk-score)
	RiskScoreActivity(ctx context.Context, request RiskScoreActivityRequestObject) (RiskScoreActivityResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

